import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"64、【未濟】 坎下離上","description":"橫渠易說 - 64、【未濟】 坎下離上","frontmatter":{"title":"64、【未濟】 坎下離上","description":"橫渠易說 - 64、【未濟】 坎下離上"},"headers":[],"relativePath":"classics/hengqu/066.md","filePath":"classics/hengqu/066.md"}'),l={name:"classics/hengqu/066.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_64、【未濟】-坎下離上" tabindex="-1">64、【未濟】 坎下離上 <a class="header-anchor" href="#_64、【未濟】-坎下離上" aria-label="Permalink to “64、【未濟】 坎下離上”">​</a></h1><h3 id="彖曰-未濟亨-柔得中也。-小狐汔濟-未出中也-濡其尾無攸利-不續終也-雖不當位-剛柔應也。" tabindex="-1">彖曰：“未濟亨”，柔得中也。“小狐汔濟”，未出中也，“濡其尾無攸利”，不續終也，雖不當位，剛柔應也。 <a class="header-anchor" href="#彖曰-未濟亨-柔得中也。-小狐汔濟-未出中也-濡其尾無攸利-不續終也-雖不當位-剛柔應也。" aria-label="Permalink to “彖曰：“未濟亨”，柔得中也。“小狐汔濟”，未出中也，“濡其尾無攸利”，不續終也，雖不當位，剛柔應也。”">​</a></h3><h3 id="象曰-火在水上-未濟-君子以慎辨物居方。" tabindex="-1">象曰：火在水上，未濟，君子以慎辨物居方。 <a class="header-anchor" href="#象曰-火在水上-未濟-君子以慎辨物居方。" aria-label="Permalink to “象曰：火在水上，未濟，君子以慎辨物居方。”">​</a></h3><h3 id="初六-濡其尾-吝。-象曰-濡其尾-亦不知極也。" tabindex="-1">初六，濡其尾，吝。 象曰：“濡其尾”，亦不知極也。 <a class="header-anchor" href="#初六-濡其尾-吝。-象曰-濡其尾-亦不知極也。" aria-label="Permalink to “初六，濡其尾，吝。 象曰：“濡其尾”，亦不知極也。”">​</a></h3><h3 id="九二-曳其輪-貞吉。-象曰-九二貞吉-中以行正也。" tabindex="-1">九二，曳其輪，貞吉。 象曰：九二貞吉，中以行正也。 <a class="header-anchor" href="#九二-曳其輪-貞吉。-象曰-九二貞吉-中以行正也。" aria-label="Permalink to “九二，曳其輪，貞吉。 象曰：九二貞吉，中以行正也。”">​</a></h3><h3 id="六三-未濟徵兇-利涉大川。-象曰-未濟徵兇-位不當也。" tabindex="-1">六三，未濟徵兇，利涉大川。 象曰：“未濟徵兇”，位不當也。 <a class="header-anchor" href="#六三-未濟徵兇-利涉大川。-象曰-未濟徵兇-位不當也。" aria-label="Permalink to “六三，未濟徵兇，利涉大川。 象曰：“未濟徵兇”，位不當也。”">​</a></h3><p>有強援於上，故利涉大川，非義躁進，兇之道也。</p><h3 id="九四-貞吉悔亡。震用伐鬼方-三年有賞於大國。-象曰-貞吉悔亡-志行也。" tabindex="-1">九四，貞吉悔亡。震用伐鬼方，三年有賞於大國。 象曰：“貞吉悔亡”，志行也。 <a class="header-anchor" href="#九四-貞吉悔亡。震用伐鬼方-三年有賞於大國。-象曰-貞吉悔亡-志行也。" aria-label="Permalink to “九四，貞吉悔亡。震用伐鬼方，三年有賞於大國。 象曰：“貞吉悔亡”，志行也。”">​</a></h3><p>剛陽之德，迫近至尊，非正而吉，悔所招也。初處險中，叛而未一，奮動討伐，其勢必克，堪上之任，是以有賞。</p><h3 id="六五-貞吉無悔-君子之光-有孚-吉。-象曰-君子之光-其暉吉也。" tabindex="-1">六五，貞吉無悔，君子之光，有孚，吉。 象曰：“君子之光”，其暉吉也。 <a class="header-anchor" href="#六五-貞吉無悔-君子之光-有孚-吉。-象曰-君子之光-其暉吉也。" aria-label="Permalink to “六五，貞吉無悔，君子之光，有孚，吉。 象曰：“君子之光”，其暉吉也。”">​</a></h3><h3 id="上九-有孚於飲酒-無咎。濡其首-有孚失是。-象曰-飲酒濡首-亦不知節也。" tabindex="-1">上九，有孚於飲酒，無咎。濡其首，有孚失是。 象曰：飲酒濡首，亦不知節也。 <a class="header-anchor" href="#上九-有孚於飲酒-無咎。濡其首-有孚失是。-象曰-飲酒濡首-亦不知節也。" aria-label="Permalink to “上九，有孚於飲酒，無咎。濡其首，有孚失是。 象曰：飲酒濡首，亦不知節也。”">​</a></h3><p>飲酒而至於濡首，不節之甚也，其必失此樂也有孚。</p>',12)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
